import sys

def my_sqrt_brute(x: int) -> int:
    if x < 2:
        return x
    i = 1
    while i * i <= x:
        i += 1
    return i - 1

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    x = int(data[0])
    print(my_sqrt_brute(x))

import sys

def my_sqrt_opt(x: int) -> int:
    if x < 2:
        return x
    lo, hi, ans = 1, x // 2, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid <= x // mid:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    x = int(data[0])
    print(my_sqrt_opt(x))

import sys

def my_sqrt_best(x: int) -> int:
    if x < 2:
        return x
    t = x // 2
    while True:
        new_t = (t + x // t) // 2
        if new_t >= t:
            return t
        t = new_t

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    x = int(data[0])
    print(my_sqrt_best(x))
